import{_ as a,H as l,o,c as d,aO as t,q as n,s as r,a as i,l as s,aU as _}from"./chunks/framework.vjUPZZJn.js";const E=JSON.parse('{"title":"ros2_control 控制器架构与 chainable 机制","description":"","frontmatter":{"date":"2026-10-29T10:00:00.000Z","title":"ros2_control 控制器架构与 chainable 机制","source":[["1-知识/机器人/ROS2/ros2_control控制器与chainable机制"]],"tags":["机器人","源码阅读","学习笔记","ROS2"],"categories":["机器人"],"permalink":"/pages/e8f063"},"headers":[],"relativePath":"机器人/ros2_control 控制器架构与 chainable 机制.md","filePath":"机器人/ros2_control 控制器架构与 chainable 机制.md","lastUpdated":1793240540000}'),m={name:"机器人/ros2_control 控制器架构与 chainable 机制.md"};function h(b,e,u,A,p,f){const c=l("Mermaid");return o(),d("div",null,[e[2]||(e[2]=t('<h1 id="ros2-control-控制器架构与-chainable-机制" tabindex="-1">ros2_control 控制器架构与 chainable 机制 <a class="header-anchor" href="#ros2-control-控制器架构与-chainable-机制" aria-label="Permalink to &quot;ros2_control 控制器架构与 chainable 机制&quot;">​</a></h1> <p>ros2_control 的源码分布在五个仓库、编译出十几个包，架构讨论里出现的角色（controller_manager、hardware_interface、chainable controller）与实际包名并不一一对应，这是读码的第一道坎。本文以 AdmittanceController（Humble 分支，commit <code>2105376</code>，即 v2.54.0 之后 4 个提交、admittance_controller 代码与 2.54.0 相同）为线索，讲清三个角色各自的职责、chainable 的准确含义、角色与包的映射，以及环境实证里容易被误判的信号。适合准备读 ros2_controllers 源码或做控制器二次开发的读者。AdmittanceController 的完整源码走查见<a href="./AdmittanceController 源码精读与全流程走查.html">本站《AdmittanceController 源码精读与全流程走查》</a>。</p> <h2 id="三个角色" tabindex="-1">三个角色 <a class="header-anchor" href="#三个角色" aria-label="Permalink to &quot;三个角色&quot;">​</a></h2> <ul><li><strong>controller_manager</strong>：100 Hz 实时循环，读硬件 → 逐个调控制器的 <code>update()</code> → 写硬件。可执行文件是 <code>ros2_control_node</code>；<code>ros2 control</code> CLI 是它的 service 客户端，服务定义在 <code>controller_manager_msgs</code> 包。</li> <li><strong>hardware_interface</strong>：关节与传感器的具名 double 接口（state / command interfaces），控制器与硬件的唯一通道。硬件侧由 <code>hardware_interface</code> 包定义 System / Sensor / Actuator；控制器侧基类在 <code>controller_interface</code> 包。</li> <li><strong>chainable controller</strong>：能被串接的控制器，从 <code>ChainableControllerInterface</code> 派生、导出 reference interfaces。AdmittanceController 导出的是 position / velocity reference interfaces。</li></ul> ',8)),(o(),n(_,null,{default:r(()=>[s(c,{id:"mermaid-26",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20T%5B%E8%BD%A8%E8%BF%B9%E8%AF%9D%E9%A2%98%5D%20--%3E%20JTC%5BJTC%3Cbr%2F%3E%E8%BD%A8%E8%BF%B9%E6%8F%92%E8%A1%A5%5D%0A%20%20%20%20JTC%20--%3E%7C%E5%8F%82%E8%80%83%7C%20ADM%5BAdmittanceController%3Cbr%2F%3E%E5%86%85%E5%90%AB%20AdmittanceRule%5D%0A%20%20%20%20FT%5B%E5%8A%9B%E4%BC%A0%E6%84%9F%E5%99%A8%3Cbr%2F%3E6%20%E4%B8%AA%20state%20interfaces%5D%20--%3E%7Cwrench%7C%20ADM%0A%20%20%20%20KDL%5Bkinematics_interface_kdl%3Cbr%2F%3EKDL%3A%20FK%20%2B%20%E9%98%BB%E5%B0%BC%E4%BC%AA%E9%80%86%E5%BE%AE%E5%88%86%20IK%5D%20-.-%20ADM%0A%20%20%20%20ADM%20--%3E%7C%E4%BF%AE%E6%AD%A3%E5%90%8E%E5%91%BD%E4%BB%A4%7C%20ARM%5B%E6%9C%BA%E6%A2%B0%E8%87%82%E7%A1%AC%E4%BB%B6%3Cbr%2F%3Ecommand%3A%20%E5%85%B3%E8%8A%82%E4%BD%8D%E7%BD%AE%5D%0A%20%20%20%20ARM%20--%3E%20JSB%5Bjoint_state_broadcaster%5D%0A%20%20%20%20JSB%20--%3E%7C%2Fjoint_states%7C%20OBS%5BRViz%20%2F%20PlotJuggler%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[i(`
          Loading...
        `,-1)])]),_:1})),e[3]||(e[3]=t('<p>CM 统一调度框内所有控制器；mock 硬件用一个 <code>hardware_interface::SystemInterface</code> 插件同时扮演力传感器和机械臂两个框。</p> <h2 id="chainable-的准确含义" tabindex="-1">chainable 的准确含义 <a class="header-anchor" href="#chainable-的准确含义" aria-label="Permalink to &quot;chainable 的准确含义&quot;">​</a></h2> <p>一个容易搞混的点：controller_manager 管理的是「多个 controller」，<strong>chainable 是其中一部分 controller 的属性，不是 controller 的定义</strong>。三种形态（实际系统里经常在同一个 CM 中同时运行这三类）：</p> <table tabindex="0"><thead><tr><th>控制器</th> <th>形态</th> <th>chainable</th></tr></thead> <tbody><tr><td><code>joint_state_broadcaster</code></td> <td>broadcaster：只读状态、发 <code>/joint_states</code> 话题，观测旁路</td> <td>否</td></tr> <tr><td><code>joint_trajectory_controller</code></td> <td>普通控制器：轨迹话题进 → 关节命令出，链的源头</td> <td>否</td></tr> <tr><td><code>admittance_controller</code></td> <td>导出 reference interfaces，可被上游串接</td> <td>是</td></tr></tbody></table> <p>两条关键性质：</p> <ol><li><strong>级联数据不走 ROS 话题</strong>。JTC → AdmittanceController 的参考传递经 reference interfaces 在 CM 的同一个 update 周期内完成，CM 按链式依赖排序（先 update 上游再 update 下游），零序列化、零 DDS 往返——这是 ros2_control 里唯一保证实时性的控制器间通道。</li> <li><strong>chainable 不等于必须被串接</strong>。AdmittanceController 保留了话题入口 <code>/admittance_controller/joint_references</code>，非级联模式可以直接喂关节参考。</li></ol> <h2 id="角色-→-包的映射" tabindex="-1">角色 → 包的映射 <a class="header-anchor" href="#角色-→-包的映射" aria-label="Permalink to &quot;角色 → 包的映射&quot;">​</a></h2> <table tabindex="0"><thead><tr><th>架构角色</th> <th>包</th> <th>说明</th></tr></thead> <tbody><tr><td>controller_manager</td> <td><code>controller_manager</code> + <code>controller_manager_msgs</code></td> <td>循环本体；CLI 的服务定义</td></tr> <tr><td>hardware_interface</td> <td><code>hardware_interface</code> + <code>controller_interface</code></td> <td>硬件侧接口；控制器侧基类（含 ChainableControllerInterface）</td></tr> <tr><td>AdmittanceController 大框</td> <td><code>admittance_controller</code></td> <td>AdmittanceRule 不是独立包，是包内类，实现在 <code>admittance_rule_impl.hpp</code></td></tr> <tr><td>JTC 框</td> <td><code>joint_trajectory_controller</code></td> <td>用 apt 版即可，无需进源码构建</td></tr> <tr><td>kinematics_interface 插件</td> <td><code>kinematics_interface</code> + <code>kinematics_interface_kdl</code></td> <td>前者纯虚接口，后者 KDL 实现，运行时 pluginlib 按参数加载</td></tr></tbody></table> <p>支撑包（依赖链上，图中不出现）：<code>realtime_tools</code>（RT-safe 的 realtime buffer / publisher，AdmittanceRule 读 wrench 经它）、<code>control_toolbox</code>（控制数学与滤波）、<code>control_msgs</code>（<code>JointTrajectory</code> 等 JTC 话题消息）、<code>ros2_control_test_assets</code> + <code>hardware_interface_testing</code>（测试用最小假机器人资产，跑 gtest 用）、<code>xacro</code> / <code>plotjuggler</code> / <code>python3-vcstool</code>（工具，不在控制回路）。</p> <p>仓库与包的对应（<code>vcs import ros2_controllers.humble.repos</code> 拉 5 个仓库，<code>colcon build --packages-up-to admittance_controller</code> 编出 12 个包）：</p> <ul><li><code>ros2_control</code> 仓库 → <code>controller_manager</code>、<code>hardware_interface</code>、<code>controller_interface</code>、<code>controller_manager_msgs</code>、<code>ros2_control_test_assets</code>、<code>hardware_interface_testing</code>（6 个）</li> <li><code>ros2_controllers</code> 仓库 → <code>admittance_controller</code></li> <li><code>kinematics_interface</code> 仓库 → <code>kinematics_interface</code>、<code>kinematics_interface_kdl</code></li> <li><code>realtime_tools</code>、<code>control_toolbox</code>、<code>control_msgs</code> 仓库 → 各 1 个</li></ul> <p>apt 的 <code>ros2-control</code> / <code>ros2-controllers</code> 是空壳 meta 包，不含代码，作用是一条命令拉齐一组包。apt 版与源码 overlay 同名包并存时，按 <code>AMENT_PREFIX_PATH</code> 顺序取排在前面的，overlay 在前——这是改源码后能生效的机制。</p> <h2 id="环境实证-ubuntu-22-04-humble" tabindex="-1">环境实证（Ubuntu 22.04 + Humble） <a class="header-anchor" href="#环境实证-ubuntu-22-04-humble" aria-label="Permalink to &quot;环境实证（Ubuntu 22.04 + Humble）&quot;">​</a></h2> <ul><li>裸启动 <code>ros2 run controller_manager ros2_control_node</code>，两条 WARN 均正常：<code>&#39;update_rate&#39; parameter not set</code> 是没给参数文件，默认 100 Hz；<code>FIFO RT scheduling … Operation not permitted</code> 是当前用户无实时调度特权（未配 rtprio limits），CM 退回普通调度，mock 硬件不受影响。</li> <li><code>ros2 control list_controller_types</code> 是运行时 service 调用，CM 不在跑会一直 waiting for service——验证插件枚举必须先起一个 CM。</li> <li><code>ros2_control_node --help</code> 不打印 usage：Humble 不识别该参数，直接启动节点。</li> <li>版本：apt 安装 <code>ros-humble-ros2-controllers</code> 2.54.0；源码 clone 的 humble 分支 HEAD 恰为 <code>2105376</code>，与本文行号锚点同版本，无需 checkout。</li></ul> <h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2> <ul><li>说「CM 管理多个 chainable controller」不准确，应为「CM 管理多个 controller，其中一部分是 chainable 的」；admittance_controller 属于 chainable 这一类。</li> <li>控制器间要实时，走 reference interfaces（CM 周期内）；不要求实时，走话题（如 JSB 的 <code>/joint_states</code>、JTC 的轨迹入口）。</li> <li>改 AdmittanceRule 只动 <code>admittance_controller</code> 一个包，重编用 <code>colcon build --packages-select admittance_controller</code>。</li></ul> <p>在此架构基础上对 AdmittanceController 生命周期的逐行走查、参数系统与 mock 硬件实测中的排坑，见<a href="./AdmittanceController 源码精读与全流程走查.html">本站《AdmittanceController 源码精读与全流程走查》</a>；导纳定律需要的六个坐标位姿的来历，见<a href="./AdmittanceTransforms 的六个位姿：导纳定律的坐标桥梁.html">本站《AdmittanceTransforms 的六个位姿：导纳定律的坐标桥梁》</a>；力控算法层面的导纳与 PI 对比，见<a href="./导纳控制与PI控制.html">本站《导纳控制与 PI 控制：力控算法的定位与对比》</a>。</p>',33))])}const g=a(m,[["render",h]]);export{E as __pageData,g as default};
